const split = (text: string) => text.trim().split(/\s+/);

export const ANSWERS: readonly string[] = split(ANSWER_TEXT);
export const EXTRA_GUESSES: readonly string[] = split(EXTRA_TEXT);
export const GUESSES: readonly string[] = [...ANSWERS, ...EXTRA_GUESSES];

const VALID = new Set<string>(GUESSES);

/** Is this a word the game accepts as a guess? */
export const isValidGuess = (word: string) => VALID.has(word.toLowerCase());
